export async function createLeadMagnetLead(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    campaign: LeadMagnetCampaignRow;
    enrollmentId: string;
    participantUsername: string | null;
    participantScopedId: string;
    platform: LeadMagnetPlatform;
    mediaId: string;
  },
): Promise<{ leadId: string; leadSubmissionId: string } | null> {
  try {
    const { data: existingEnrollment } = await admin
      .from("lead_magnet_enrollments")
      .select("id, lead_id, lead_submission_id")
      .eq("id", args.enrollmentId)
      .maybeSingle();

    if (existingEnrollment?.lead_id) {
      return {
        leadId: String(existingEnrollment.lead_id),
        leadSubmissionId: String(existingEnrollment.lead_submission_id ?? ""),
      };
    }

    const canonicalProfile = await getParticipantProfile(admin, {
      organizationId: args.organizationId,
      platform: args.platform,
      participantScopedId: args.participantScopedId,
    });

    if (canonicalProfile?.canonical_lead_id && canonicalProfile.canonical_submission_id) {
      await admin
        .from("lead_magnet_enrollments")
        .update({
          lead_id: canonicalProfile.canonical_lead_id,
          lead_submission_id: canonicalProfile.canonical_submission_id,
          updated_at: new Date().toISOString(),
        })
        .eq("id", args.enrollmentId);
      return {
        leadId: canonicalProfile.canonical_lead_id,
        leadSubmissionId: canonicalProfile.canonical_submission_id,
      };
    }

    const actor = await getOrCreateSystemActor(admin, args.organizationId);
    const statusId = await resolveLeadStatusId(admin, args.organizationId, "new");
    const accountLabel = await resolveLeadMagnetAccountLabel(admin, {
      organizationId: args.organizationId,
      campaignId: args.campaign.id,
      platform: args.platform,
      legacyAccountId: args.campaign.account_id,
    });

    const displayName = (args.participantUsername ?? "").trim().replace(/^@/, "") ||
      `${args.platform === "instagram" ? "IG" : "FB"} ${args.participantScopedId.slice(0, 8)}`;
    const now = new Date().toISOString();
    const channelLabel = args.platform === "instagram" ? "Instagram Comment" : "Facebook Comment";

    const leadId = crypto.randomUUID();
    const ticketId = "LEAD-" + leadId.replace(/-/g, "").slice(0, 8).toUpperCase();

    const { error: leadErr } = await admin.from("leads").insert({
      id: leadId,
      ticket_id: ticketId,
      client: displayName,
      title: `Lead Magnet — ${args.campaign.name}`.slice(0, 120),
      category: "Lead Magnet",
      source: "Lead Magnet",
      services: channelLabel,
      organization_id: args.organizationId,
      created_by: actor.userId,
      created_by_name: accountLabel,
      assignee: "Unassigned",
      status_id: statusId,
      web_id: null,
      created_at: now,
      updated_at: now,
    });

    if (leadErr) {
      console.error("[lead-magnet] leads insert failed:", leadErr.message);
      return null;
    }

    const submissionId = crypto.randomUUID();
    const submissionPayload: Record<string, unknown> = {
      id: submissionId,
      organization_id: args.organizationId,
      lead_id: leadId,
      form_id: null,
      name: displayName,
      status: "draft",
      is_active: true,
      lead_magnet_enrollment_id: args.enrollmentId,
      lead_magnet_campaign_id: args.campaign.id,
      notes: `Lead magnet keyword "${args.campaign.keyword}" on media ${args.mediaId}`,
      updated_at: now,
    };

    const { error: subErr } = await admin.from("lead_submissions").insert(submissionPayload);

    if (subErr) {
      console.error("[lead-magnet] lead_submissions insert failed:", subErr.message);
      return { leadId, leadSubmissionId: submissionId };
    }

    await admin
      .from("lead_magnet_enrollments")
      .update({ lead_id: leadId, lead_submission_id: submissionId, updated_at: now })
      .eq("id", args.enrollmentId);

    await upsertParticipantContactField(admin, {
      organizationId: args.organizationId,
      platform: args.platform,
      participantScopedId: args.participantScopedId,
      canonicalLeadId: leadId,
      canonicalSubmissionId: submissionId,
      phoneNumber: canonicalProfile?.phone_number ?? null,
      email: canonicalProfile?.email ?? null,
    });

    return { leadId, leadSubmissionId: submissionId };
  } catch (err) {
    console.error("[lead-magnet] createLeadMagnetLead error:", err);
    return null;
  }
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { buildLeadMagnetDownloadUrl } from "../leadMagnetActionUrl.ts";
import { interpolateLeadMagnetText } from "../types.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";
import { buildLeadMagnetAssetPublicUrl } from "../deliveryAsset.ts";

export type DeliveryContext = {
  username: string;
  deliveryUrl: string;
  campaignName: string;
};

export async function buildDeliveryContext(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
  },
): Promise<DeliveryContext> {
  const username = (args.enrollment.participant_username ?? "").trim().replace(/^@/, "") || "Kak";
  let deliveryUrl = String(args.campaign.delivery_url ?? "").trim();

  const storagePath = (args.campaign as { delivery_storage_path?: string | null }).delivery_storage_path;
  if (storagePath?.trim()) {
    const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").trim();
    if (supabaseUrl) {
      deliveryUrl = buildLeadMagnetAssetPublicUrl(supabaseUrl, storagePath.trim());
    }
  }

  if (!deliveryUrl) {
    deliveryUrl = await buildLeadMagnetDownloadUrl(args.enrollment.id);
  }

  return {
    username,
    deliveryUrl,
    campaignName: args.campaign.name,
  };
}

export function interpolateDeliveryTemplate(
  template: string,
  ctx: DeliveryContext,
): string {
  return template
    .replace(/\{\{username\}\}/gi, ctx.username)
    .replace(/\{\{delivery_url\}\}/gi, ctx.deliveryUrl)
    .replace(/\{\{campaign_name\}\}/gi, ctx.campaignName);
}

export function interpolateCampaignText(
  template: string,
  username: string | null,
): string {
  return interpolateLeadMagnetText(template, username);
}

export type WhatsAppTemplateParams = {
  body?: string[];
  header?: string[];
  button?: string[];
};

export function buildWhatsAppTemplateComponents(
  params: WhatsAppTemplateParams | null | undefined,
  ctx: DeliveryContext,
): Array<Record<string, unknown>> {
  const components: Array<Record<string, unknown>> = [];
  const mapVars = (vars: string[] | undefined): string[] =>
    (vars ?? []).map((v) => interpolateDeliveryTemplate(v, ctx));

  const bodyVars = mapVars(params?.body);
  if (bodyVars.length > 0) {
    components.push({
      type: "body",
      parameters: bodyVars.map((text) => ({ type: "text", text })),
    });
  }

  const headerVars = mapVars(params?.header);
  if (headerVars.length > 0) {
    components.push({
      type: "header",
      parameters: headerVars.map((text) => ({ type: "text", text })),
    });
  }

  const buttonVars = mapVars(params?.button);
  if (buttonVars.length > 0) {
    components.push({
      type: "button",
      sub_type: "url",
      index: "0",
      parameters: buttonVars.map((text) => ({ type: "text", text })),
    });
  }

  return components;
}
